return {["fb37_01"]={["down"]=[[fb37_04]],["dsc"]=[[此地又名万寿山，是一片风景秀丽的皇家园林。在幽静的松柏林中，一片郁郁葱葱的喜人绿意，显得苍老和雄劲，也含蕴着无限的妩媚风光。]],["fightBackground"]=[[森林内]],["id"]=[[fb37_01]],["item1"]=[[fb37item46]],["item2"]=[[ycitem1]],["name"]=[[景山]],["permission"]=2,["role1"]=[[fb37item43]],["role2"]=[[fb37item29]],["role3"]=[[fb37item44]],["role4"]=[[fb37item45]],["stepMusic"]=[[jiaobu]]},["fb37_02"]={["down"]=[[fb37_35]],["dsc"]=[[这里是内城的一角，头上的天空只能见方方的一角。上面有座漂亮的角楼。]],["id"]=[[fb37_02]],["name"]=[[城角]],["permission"]=2,["right"]=[[fb37_03]],["rightDown"]=[[fb37_07]],["stepMusic"]=[[jiaobu]]},["fb37_03"]={["dsc"]=[[这是内外城间的宫道。平日里一些人物出入内宫，就是走这路的。这宫道上每日都有御林军来回巡逻，出入可要小心。宫道两边高高的红墙，正是为了拦阻入侵高手的。]],["id"]=[[fb37_03]],["left"]=[[fb37_02]],["name"]=[[宫道]],["permission"]=2,["right"]=[[fb37_04]],["stepMusic"]=[[jiaobu]]},["fb37_04"]={["down"]=[[fb37_08]],["dsc"]=[[这里是皇城的北门，呈凹字形的建筑，与午门合称两阙，是防御和保卫皇城的宫门。门楼重檐庑殿顶，内设钟鼓，黄昏时鸣钟百零八响，而后起更击鼓报时，直到次日拂晓鸣钟。每年筛选秀女，应选女子皆从此门入宫。]],["id"]=[[fb37_04]],["left"]=[[fb37_03]],["name"]=[[神武门]],["permission"]=2,["right"]=[[fb37_05]],["role1"]=[[fb37r04_1]],["role2"]=[[fb37r04_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_01]]},["fb37_05"]={["dsc"]=[[这是内外城间的宫道。平日里一些人物出入内宫，就是走这路的。这宫道上每日都有御林军来回巡逻，出入可要小心。宫道两边高高的红墙，正是为了拦阻入侵高手的。]],["id"]=[[fb37_05]],["left"]=[[fb37_04]],["name"]=[[宫道]],["permission"]=2,["right"]=[[fb37_06]],["stepMusic"]=[[jiaobu]]},["fb37_06"]={["down"]=[[fb37_43]],["dsc"]=[[这里是内城的一角，头上的天空只能见方方的一角。上面有座漂亮的角楼。]],["id"]=[[fb37_06]],["left"]=[[fb37_05]],["leftDown"]=[[fb37_09]],["name"]=[[城角]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb37_07"]={["dsc"]=[[角楼中央是一个三开间的方亭楼，四出抱厦。最顶部十字脊镀金宝顶以下，计有三层檐，九梁，十八柱，七十二条脊，上下重叠，纵横交错。底座是白玉石台基周围饰以白玉栏杆。它紧扼内城一角，能控制四下，内城四角各有一座这样的角楼，若有风吹草动，都可一清二楚。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_07]],["leftUp"]=[[fb37_02]],["name"]=[[角楼]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb37_08"]={["down"]=[[fb37_10]],["dsc"]=[[钦安殿位于御花园内，殿顶为平顶四坡式，周围有汉白玉石栏板。殿内供奉玄武大帝，殿旁有鱼池假山，奇花异树。北边穿过御花园垒石砌就的堆秀山，就是皇宫的北门神武门了。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_08]],["name"]=[[钦安殿]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_04]]},["fb37_09"]={["dsc"]=[[角楼中央是一个三开间的方亭楼，四出抱厦。最顶部十字脊镀金宝顶以下，计有三层檐，九梁，十八柱，七十二条脊，上下重叠，纵横交错。底座是白玉石台基周围饰以白玉栏杆。它紧扼内城一角，能控制四下，内城四角各有一座这样的角楼，若有风吹草动，都可一清二楚。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_09]],["name"]=[[角楼]],["permission"]=2,["rightUp"]=[[fb37_06]],["stepMusic"]=[[jiaobu]]},["fb37_10"]={["down"]=[[fb37_15]],["dsc"]=[[这里是皇上赏花的御花园。平日里皇上时常会来这儿，和诸宫娘娘一起赏花品茗。所以，这儿是平常太监、侍卫不能来的。这里的宫女多是心灵手巧，精通花道的。放眼四顾，满目皆是似锦繁花，你仔细分辨，竟然品目齐全，但凡你想得的，甚至你想都不敢想的，这里都有了。你不禁有些嫉妒起皇帝老儿来。]],["fightBackground"]=[[森林外]],["id"]=[[fb37_10]],["item1"]=[[fb37item13]],["item2"]=[[fb37item16]],["item3"]=[[fb37item17]],["name"]=[[御花园]],["permission"]=1,["right"]=[[fb37_11]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_08]]},["fb37_100"]={["down"]=[[fb37_104]],["dsc"]=[[这里是六部之首:吏部官员候朝的朝房。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_100]],["name"]=[[吏部公署]],["permission"]=1,["role1"]=[[fb37r100_1]],["stepMusic"]=[[jiaobu]]},["fb37_101"]={["dsc"]=[[这里是六部之一:刑部官员候朝的朝房。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_101]],["item1"]=[[bfitem2]],["name"]=[[刑部公署]],["permission"]=2,["right"]=[[fb37_102]],["role1"]=[[fb37r101_1]],["stepMusic"]=[[jiaobu]]},["fb37_102"]={["down"]=[[fb37_106]],["dsc"]=[[这是通往各部官员朝房的左门。西庑房设的是兵、刑、礼三部。]],["id"]=[[fb37_102]],["left"]=[[fb37_101]],["name"]=[[左阙门]],["permission"]=1,["right"]=[[fb37_103]],["role1"]=[[fb37r102_1]],["role2"]=[[fb37item55]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_99]]},["fb37_103"]={["down"]=[[fb37_108]],["dsc"]=[[这里是皇帝廷杖官吏的地方，也是大将得胜还朝后举行献俘礼仪的场所。每年十月初一日，在这里向全国颁发来年历书，时称“颁朔”。在内金水河上的五座汉白玉雕桥，造型秀丽，同雄伟壮观的午门城楼和金碧辉煌的太和门相映，引人注目。]],["id"]=[[fb37_103]],["item1"]=[[bfitem1]],["left"]=[[fb37_102]],["name"]=[[午门广场]],["permission"]=1,["right"]=[[fb37_104]],["role1"]=[[fb37r103_1]],["role2"]=[[fb37r103_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_96]]},["fb37_104"]={["down"]=[[fb37_107]],["dsc"]=[[这是通往各部官员朝房的右门。东庑房设的是吏、户、工三部。]],["id"]=[[fb37_104]],["left"]=[[fb37_103]],["name"]=[[右阙门]],["permission"]=1,["right"]=[[fb37_105]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_100]]},["fb37_105"]={["dsc"]=[[这里是六部之一:户部官员候朝的朝房。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_105]],["left"]=[[fb37_104]],["name"]=[[户部公署]],["permission"]=2,["role1"]=[[fb37r105_1]],["role2"]=[[fb37r105_2]],["stepMusic"]=[[jiaobu]]},["fb37_106"]={["dsc"]=[[这里是六部之一:礼部官员候朝的朝房。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_106]],["name"]=[[礼部公署]],["permission"]=2,["role1"]=[[fb37r106_1]],["role2"]=[[fb37r106_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_102]]},["fb37_107"]={["dsc"]=[[这里是六部之一:工部官员候朝的朝房。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_107]],["name"]=[[工部公署]],["permission"]=2,["role1"]=[[fb37r107_1]],["role2"]=[[fb37r107_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_104]]},["fb37_108"]={["dsc"]=[[五座金水石桥横卧金水河上，中间那座桥是专供皇帝使用的，称为“御路桥”，桥的柱头全为龙形，人称“蟠龙柱”。两边为王公桥，桥的柱头雕成“荷花柱”。桥下是金水河缓缓的流水。水看上去很清，据说曾有人在这里跳河。这里是进皇宫正门的必经之路。]],["id"]=[[fb37_108]],["item1"]=[[fb37item87]],["name"]=[[小桥]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_103]]},["fb37_11"]={["down"]=[[fb37_14]],["dsc"]=[[这儿是皇帝阅览书籍和游玩的地方，也是一座珍宝馆，其中多是全国各地上贡的珠宝珍奇。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_11]],["left"]=[[fb37_10]],["name"]=[[颐和轩]],["permission"]=2,["role1"]=[[fb37r11_1]],["stepMusic"]=[[jiaobu]]},["fb37_12"]={["dsc"]=[[御花园两边建有鱼池，池上建亭，这里就是澄瑞亭。亭子朝南抱厦，亭座下有涵洞，洞中有井。夏日，池水清澈，金鱼戏游于荷花之下。冬日，池水结冰，金鱼就入井过冬。]],["fightBackground"]=[[森林外]],["id"]=[[fb37_12]],["item1"]=[[fb37r12_1]],["item2"]=[[fb37r12_2]],["name"]=[[澄瑞亭]],["permission"]=2,["rightDown"]=[[fb37_15]],["stepMusic"]=[[jiaobu]]},["fb37_13"]={["dsc"]=[[御花园两边建有鱼池，池上建亭，这里就是浮碧亭。亭子朝南抱厦，亭座下有涵洞，洞中有井。夏日，池水清澈，金鱼戏游于荷花之下。冬日，池水结冰，金鱼就入井过冬。]],["fightBackground"]=[[森林外]],["id"]=[[fb37_13]],["leftDown"]=[[fb37_15]],["name"]=[[浮碧亭]],["permission"]=2,["role1"]=[[fb37r13_1]],["stepMusic"]=[[jiaobu]]},["fb37_14"]={["down"]=[[fb37_16]],["dsc"]=[[这里是为皇上赋诗、祝寿的地方。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_14]],["item1"]=[[bfitem4]],["name"]=[[乐寿堂]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_11]]},["fb37_15"]={["down"]=[[fb37_24]],["dsc"]=[[这里是皇上赏花的御花园。平日里皇上时常会来这儿，和诸宫娘娘一起赏花品茗。所以，这儿是平常太监，侍卫不能来的。这里的宫女多是心灵手巧，精通花道的。放眼四顾，满目皆是似锦繁花，你仔细分辨，竟然品目齐全，但凡你想得的，甚至你想都不敢想的，这里都有了。你不禁有些嫉妒起皇帝老儿来。]],["fightBackground"]=[[森林外]],["id"]=[[fb37_15]],["item1"]=[[fb37item15]],["item2"]=[[fb37item18]],["item3"]=[[fb37item19]],["leftDown"]=[[fb37_18]],["leftUp"]=[[fb37_12]],["name"]=[[御花园]],["permission"]=1,["rightDown"]=[[fb37_19]],["rightUp"]=[[fb37_13]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_10]]},["fb37_16"]={["dsc"]=[[如果有皇帝退位，做了太上皇就会居住在此。太上皇不再来问朝政，就在此休息，静心养性。直至寿终正寝。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_16]],["item1"]=[[fb37item32]],["name"]=[[养性殿]],["permission"]=2,["right"]=[[fb37_17]],["role1"]=[[fb37r16_1]],["role2"]=[[fb37r16_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_14]]},["fb37_17"]={["down"]=[[fb37_20]],["dsc"]=[[这是宫内最大的戏台，每逢年节和皇上生日，帝皇后妃都来这里看戏。平日里偶尔太后也会来这点上几折子看看。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_17]],["left"]=[[fb37_16]],["name"]=[[畅音阁]],["permission"]=2,["role1"]=[[fb37r17_1]],["role2"]=[[fb37r17_2]],["stepMusic"]=[[jiaobu]]},["fb37_18"]={["dsc"]=[[千秋亭上圆下方，抱厦四出，上层伞状圆顶与下层众多进出的檐角，组织得极其巧妙。]],["fightBackground"]=[[森林外]],["id"]=[[fb37_18]],["name"]=[[千秋亭]],["permission"]=2,["rightUp"]=[[fb37_15]],["stepMusic"]=[[jiaobu]]},["fb37_19"]={["dsc"]=[[万春亭，亭上圆下方，抱厦四出，上层伞状圆顶与下层众多进出的檐角，组织得极其巧妙。]],["fightBackground"]=[[森林外]],["id"]=[[fb37_19]],["leftUp"]=[[fb37_15]],["name"]=[[万春亭]],["permission"]=2,["role1"]=[[fb37r19_1]],["stepMusic"]=[[jiaobu]]},["fb37_20"]={["down"]=[[fb37_47]],["dsc"]=[[这里是先太上皇起居休憩的地方。现下却是公主寝宫。只见墙壁上、桌椅上，都是刀剑皮鞭之类的兵器，便如是个武人的居室，哪里像是金枝玉叶的公主寝室。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_20]],["item1"]=[[fb37item37]],["item2"]=[[fb37item38]],["name"]=[[宁寿宫]],["permission"]=2,["role1"]=[[fb37r20_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_17]]},["fb37_21"]={["down"]=[[fb37_28]],["dsc"]=[[这里已是深宫内院。陈列着一些工艺美术，这就是后妃嫔女居住的地方。进了这儿可以深深感受到何谓“一入宫门深似海”。宫中挂着一个红木牌匾:“茂修内治”。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_21]],["item1"]=[[fb37item40]],["item2"]=[[fb37item36]],[