32]]},["fb37_41"]={["dsc"]=[[飞檐雕栏的厅廊。两边是喜人的花草，站在这儿，隐约听得到后宫里嫔妃宫女们嬉笑的声音，宫里的人来来往往的，显得井井有条，看来宫里的规矩挺严的。]],["id"]=[[fb37_41]],["left"]=[[fb37_40]],["name"]=[[厅廊]],["permission"]=2,["right"]=[[fb37_42]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_33]]},["fb37_42"]={["dsc"]=[[这里已是深宫内院。陈列着一些工艺美术，这就是后妃嫔女居住的地方。进了这儿可以深深感受到何谓“一入宫门深似海”。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_42]],["item1"]=[[fb37item36]],["item2"]=[[fb37item38]],["left"]=[[fb37_41]],["name"]=[[延禧宫]],["permission"]=2,["role1"]=[[fb37r42_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_34]]},["fb37_43"]={["down"]=[[fb37_68]],["dsc"]=[[这是内外城间的宫道。平日里一些人物出入内宫，就是走这路的。这宫道上每日都有大内侍卫来回巡逻，出入可要小心。宫道两边高高的红墙，正是为了拦阻入侵高手的。]],["id"]=[[fb37_43]],["name"]=[[宫道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_06]]},["fb37_44"]={["dsc"]=[[这是皇上放置图书翰墨以及内廷儒臣值班的懋勤殿。皇帝少年时曾在此读书。此处藏书甚多，多为内府编刊的各类新书。天下刑法人命关天。每年秋后，在此审断一次，故称“秋审”。后世“秋后算账”也是源于此。被朱笔划勾者，断无生理，称“勾到”或“勾决”。因在懋勤殿勾决，故又称“懋勤殿勾到”。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_44]],["name"]=[[懋勤殿]],["permission"]=2,["right"]=[[fb37_45]],["role1"]=[[fb37r44_1]],["stepMusic"]=[[jiaobu]]},["fb37_45"]={["down"]=[[fb37_59]],["dsc"]=[[这是皇上的寝宫。乾清意为天下清宁平和。皇上也常在这里选派官吏，批阅文章，召见臣下。宫上横匾“正大光明”，历代皇上以此表明自己所作所为是正直大度和光明磊落的。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_45]],["item1"]=[[fb37item6]],["item2"]=[[fb37item37]],["item3"]=[[fb37item91]],["left"]=[[fb37_44]],["leftDown"]=[[fb37_48]],["name"]=[[乾清宫]],["permission"]=1,["right"]=[[fb37_46]],["rightDown"]=[[fb37_49]],["role1"]=[[fb37r45_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_39]]},["fb37_46"]={["dsc"]=[[这是皇上贮存冠袍带履和轿舆的端凝殿。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_46]],["left"]=[[fb37_45]],["name"]=[[端凝殿]],["permission"]=2,["role1"]=[[fb37r46_1]],["stepMusic"]=[[jiaobu]]},["fb37_47"]={["down"]=[[fb37_51]],["dsc"]=[[这里是宫中仅次于御花园的花园中心。皇极殿前是宁寿门，后通宁寿宫，宁寿宫便是最受皇上宠爱的平遥公主的寝宫所在了。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_47]],["name"]=[[皇极殿]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_20]]},["fb37_48"]={["dsc"]=[[这是宫内的监办处，是宫中太监的管理机构，太监总管都在此地。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_48]],["name"]=[[敬事房]],["permission"]=2,["rightUp"]=[[fb37_45]],["role1"]=[[fb37r48_1]],["stepMusic"]=[[jiaobu]]},["fb37_49"]={["dsc"]=[[皇上用功读书的御书房，又叫上书房、南书房。也是皇子皇孙们读书的地方。北面是开国皇帝御笔的牌匾，两侧是先皇御笔楹联。四下齐整地排着几张书架，上面看来都是些名典巨著。你暗自想，原来皇帝也读这么多的书啊。书房正中有张精雕的檀香木书桌，桌上摆着几本封面精美的书。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_49]],["item1"]=[[fb37item2]],["item2"]=[[fb37item3]],["item3"]=[[fb37item7]],["leftUp"]=[[fb37_45]],["name"]=[[御书房]],["permission"]=1,["role1"]=[[fb37r49_1]],["role2"]=[[fb37item85]],["stepMusic"]=[[jiaobu]]},["fb37_50"]={["down"]=[[fb37_55]],["dsc"]=[[奉先殿是皇宫中至要之所。殿里供奉着历代皇帝的图像。一旦有何重大决策，皇帝都会亲自来此，奉告列祖列宗。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_50]],["name"]=[[奉先殿]],["permission"]=2,["role1"]=[[fb37item74]],["role2"]=[[fb37item75]],["role3"]=[[fb37item76]],["stepMusic"]=[[jiaobu]]},["fb37_51"]={["down"]=[[fb37_62]],["dsc"]=[[这里是宁寿宫的大门。往北进去就是太上皇休憩的宁寿宫了。]],["id"]=[[fb37_51]],["name"]=[[宁寿门]],["permission"]=2,["role1"]=[[fb37r51_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_47]]},["fb37_52"]={["down"]=[[fb37_56]],["dsc"]=[[这是慈宁宫后的大佛堂。堂里供着一尊如来佛像，佛像前是一张供桌。桌上点着盏油灯。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_52]],["item1"]=[[fb37item31]],["name"]=[[大佛堂]],["permission"]=2,["role1"]=[[fb37r52_1]],["stepMusic"]=[[jiaobu]]},["fb37_53"]={["dsc"]=[[这是一排不起眼的房舍。但这排又矮又小的房子其实非同寻常，这是辅佐皇帝的最高政务机构，以处理西北军务为名的设军机房，又名办理军机处。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_53]],["name"]=[[军机处]],["permission"]=2,["rightDown"]=[[fb37_59]],["role1"]=[[fb37r53_1]],["role2"]=[[fb37r53_2]],["stepMusic"]=[[jiaobu]]},["fb37_54"]={["dsc"]=[[这里是六部尚书和都察院御史、大理寺卿、通政使司通政使等九卿官员以及王公、贝勒大臣等候皇上召见的场所，对面是蒙古王公值房，所以也叫“待漏房”。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_54]],["leftDown"]=[[fb37_59]],["name"]=[[九卿房]],["permission"]=2,["role1"]=[[fb37r54_1]],["role2"]=[[fb37r54_2]],["stepMusic"]=[[jiaobu]]},["fb37_55"]={["down"]=[[fb37_61]],["dsc"]=[[奉先殿庭院的大门。]],["id"]=[[fb37_55]],["name"]=[[奉先门]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_50]]},["fb37_56"]={["down"]=[[fb37_64]],["dsc"]=[[这是太后的寝宫。东西两面是暖阁。东暖阁里是太后的雕花大床。北面是个大佛堂，历朝太后除了祭祀萨满，几乎无一例外地礼佛。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_56]],["item1"]=[[fb37item37]],["item2"]=[[fb37item38]],["name"]=[[慈宁宫]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_52]]},["fb37_57"]={["dsc"]=[[养心殿是皇帝居住和处理日常政务的地方。在北墙上悬挂着一个匾额，宝座屏风上有先皇御笔题字。东暖阁竖着开国皇帝圣训八条。西暖阁里，“勤政亲贤”横幅下，是一幅先皇的御笔楹联。这是也一些官员在选拔，调动前被带来见圣的地方。书架上存放着一些关于老皇帝治理国家的经验、教训的书籍，是供皇子们学习的。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_57]],["name"]=[[养心殿]],["permission"]=2,["right"]=[[fb37_58]],["role1"]=[[fb37r57_1]],["role2"]=[[fb37r57_2]],["stepMusic"]=[[jiaobu]]},["fb37_58"]={["dsc"]=[[月华门北边是批本处，南边是奏事房，这里是皇帝经常出行坐轿的地方。]],["id"]=[[fb37_58]],["left"]=[[fb37_57]],["name"]=[[月华门]],["permission"]=2,["right"]=[[fb37_59]],["role1"]=[[fb37r58_1]],["role2"]=[[fb37r58_2]],["stepMusic"]=[[jiaobu]]},["fb37_59"]={["down"]=[[fb37_71]],["dsc"]=[[这是皇宫后廷的正门。门中有一个宝座，有些时候，皇上为表示亲政，就在这听取各衙门主管依次奏事，被称作御门听政。]],["id"]=[[fb37_59]],["item1"]=[[fb37r59_5]],["left"]=[[fb37_58]],["leftDown"]=[[fb37_65]],["leftUp"]=[[fb37_53]],["name"]=[[乾清门]],["permission"]=1,["right"]=[[fb37_60]],["rightDown"]=[[fb37_66]],["rightUp"]=[[fb37_54]],["role1"]=[[fb37r59_1]],["role2"]=[[fb37r59_2]],["role3"]=[[fb37r59_3]],["role4"]=[[fb37r59_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_45]]},["fb37_60"]={["dsc"]=[[这里是皇帝经常出行坐轿的地方。]],["id"]=[[fb37_60]],["left"]=[[fb37_59]],["name"]=[[日精门]],["permission"]=2,["right"]=[[fb37_61]],["stepMusic"]=[[jiaobu]]},["fb37_61"]={["dsc"]=[[这儿是皇太孙读书的地方。太孙年幼，不肯用功，于是皇上就找来一些皇族的幼儿来陪太孙。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_61]],["item1"]=[[fb37item49]],["item2"]=[[fb37item36]],["item3"]=[[fb37item38]],["left"]=[[fb37_60]],["name"]=[[毓庆宫]],["permission"]=2,["right"]=[[fb37_62]],["role1"]=[[fb37r61_1]],["role2"]=[[fb37r61_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_55]]},["fb37_62"]={["down"]=[[fb37_67]],["dsc"]=[[皇极殿庭院的大门。由此往北，是皇帝休憩和太上皇养老饴孙的地方，俗称“外东路”。门前就是享誉海内外的九龙壁了。]],["id"]=[[fb37_62]],["left"]=[[fb37_61]],["name"]=[[皇极门]],["permission"]=2,["role1"]=[[fb37item70]],["role2"]=[[fb37item71]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_51]]},["fb37_63"]={["down"]=[[fb37_82]],["dsc"]=[[这是内外城间的宫道。平日里一些人物出入内宫，就是走这路的。这宫道上每日都有御林军来回巡逻，出入可要小心。宫道两边高高的红墙，正是为了拦阻入侵高手的。]],["id"]=[[fb37_63]],["item1"]=[[fb37item89]],["name"]=[[宫道]],["permission"]=2,["right"]=[[fb37_64]],["role1"]=[[fb37r63_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_35]]},["fb37_64"]={["down"]=[[fb37_69]],["dsc"]=[[这是皇宫中太后起居宫院慈宁宫的院门。门内是个小院，院里小花园里有个荷花塘，后面连着慈宁宫。]],["id"]=[[fb37_64]],["left"]=[[fb37_63]],["name"]=[[慈宁门]],["permission"]=2,["right"]=[[fb37_65]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_56]]},["fb37_65"]={["down"]=[[fb37_70]],["dsc"]=[[此门是通往宫外西路的大门。外西路是太后的居所。隆宗门外就是慈宁宫了。]],["id"]=[[fb37_65]],["left"]=[[fb37_64]],["name"]=[[隆宗门]],["permission"]=1,["rightDown"]=[[fb37_71]],["rightUp"]=[[fb37_59]],["role1"]=[[fb37r65_1]],["role2"]=[[fb37r65_2]],["stepMusic"]=[[jiaobu]]},["fb37_66"]={["down"]=[[fb37_72]],["dsc"]=[[此门是通往宫外东路的大门。外东路是太上皇的居所。景运门外空地上有一座箭亭，又称紫金箭亭，皇上常在这和王公大臣们一齐射箭，操练武艺。]],["id"]=[[fb37_66]],["leftDown"]=[[fb37_71]],["leftUp"]=[[fb37_59]],["name"]=[[景运门]],["permission"]=1,["right"]=[[fb37_67]],["stepMusic"]=[[jiaobu]]},["fb37_67"]={["down"]=[[fb37_74]],["dsc"]=[[在一大片空地上有一座箭亭，皇上常在这和王公大臣们一齐射箭，操练武艺。]],["id"]=[[fb37_67]],["left"]=[[fb37_66]],["name"]=[[紫禁箭亭]],["permission"]=2,["right"]=[[fb37_68]],["role1"]=[[fb37r67_1]],["role2"]=[[fb37r67_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_62]]},["fb37_68"]={["down"]=[[fb37_86]],["dsc"]=[[这是内外城间的宫道。平日里一些人物出入内宫，就是走这路的。这宫道上每日都有御林军来回巡逻，出入可要小心。宫道两边高高的红墙，正是为了拦阻入侵高手的。]],["id"]=[[fb37_68]],["left"]=[[fb37_67]],["name"]=[[宫道]],["permission"]=2,["role1"]=[[fb37r68_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_43]]},["fb37_69"]={["dsc"]=[[屋中空空洞洞，墙壁边倚着几个牛皮的人形，梁上垂下来几只大布袋，里面似乎装作米麦或是沙土，此外便只有一张桌子，桌前挂着块桌帷。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_69]],["name"]=[[布库房]],["permission"]=2,["role1"]=[[fb37r69_1]],["role2"]=[[fb37r69_2]],["role3"]=[[fb37r69_3]],["role4"]=[[fb37r69_4]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_64]]},["fb37_70"]={["down"]=[[fb37_77]],["dsc"]=[[这里是三大殿周围的通道。宫禁森严，天威莫测，来来往往的宫女太监虽然很多，可是谁也不敢带出一点声来。]],["id"]=[[fb37_70]],["name"]=[[永巷]],["permission"]=1,["right"]=[[fb37_71]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_65]]},["fb37_71"]={["down"]=[[fb37_75]],["dsc"]=[[碉栏玉砌，金玉堂皇，这才是皇族气范。飞檐敞椽，支撑天地的大柱正是八部天龙。这里是三殿之一保和殿。保和的意思是保持事物的协调。这座建筑的重檐歇山顶式，是皇帝举行殿试的场所以及岁末除夕赐宴外藩王公的地方。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_71]],["left"]=[[fb37_70]],["leftUp"]=[[fb37_65]],["name"]=[[保和殿]],["permission"]=2,["right"]=[[fb37_72]],["rightUp"]=[[fb37_66]],["role1"]=[[fb37200_1]],["role2"]=[[fb37200_2]],["role3"]=[[fb37200_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_59]]},["fb37_72"]={["down"]=[[fb37_79]],["dsc"]=[[这里是三大殿周围的通道。宫禁森严，天威莫测，来来往往的宫女太监虽然很多，可是谁也不敢带出一点声来。]],["id"]=[[fb37_72]],["left"]=[[fb37_71]],["name"]=[[永巷]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_66]]},["fb37_73"]={["dsc"]=[[清和殿，这是皇上、皇后用膳的地方。皇后不喜欢吵闹，所以宫人们不得大声说话。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_73]],["name"]=[[清和殿]],["permission"]=2,["right"]=[[fb37_74]],["role1"]=[[fb37r73_1]],["role2"]=[[fb37r73_2]],["role3"]=[[fb37item58]],["stepMusic"]=[[jiaobu]]},["fb37_74"]={["down"]=[[fb37_76]],["dsc"]=[[远远就能闻到一阵阵香味从这儿飘出。这里是御膳房。闲杂人等不能在此出入。一张张长桌上摆着天下美味，无不令人垂涎三尺。可这是皇上吃的，你想也甭想。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_74]],["left"]=[[fb37_73]],["name"]=[[御膳房]],["permission"]=2,["role1"]=[[fb37r74_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_67]]},["fb37_75"]={["down"]=[[fb37_78]],["dsc"]=[[碉栏玉砌，金玉堂皇，这才是皇族气范。飞檐敞椽，支撑天地的大柱正是八部天龙。这里是三殿之一中和殿。中和取意不偏不倚，就是说凡事要恰如其份。这座四角攒尖顶亭式建筑是皇帝到太和殿参加大典前休息准备和演习礼仪的地方。每年春播之季，皇帝在此阅看种子和农具，以示殷意。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_75]],["name"]=[[中和殿]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_71]]},["fb37_76"]={["dsc"]=[[这里是清和殿后院。院里种着些青菜。墙角有一口水井。站在水井边往下看，只觉深不见底，井壁上满是滑溜溜的青苔。一个轱辘吊着一根长绳，绳端系着一个木桶。北边是一条走廊，通往御膳房。]],["id"]=[[fb37_76]],["name"]=[[清和殿后院]],["permission"]=2,["role1"]=[[fb37r76_1]],["role2"]=[[fb37item66]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_74]]},["fb37_77"]={["dsc"]=[[这里是三大殿周围的通道。宫禁森严，天威莫测，来来往往的宫女太监虽然很多，可是谁也不敢带出一点声来。]],["id"]=[[fb37_77]],["name"]=[[永巷]],["permission"]=1,["right"]=[[fb37_78]],["role1"]=[[fb37r77_1]],["role2"]=[[fb37r77_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_70]]},["fb37_78"]={["down"]=[[fb37_81]],["dsc"]=[[这就是金銮宝殿。朱红殿柱，彩绘栋梁，琉璃瓦顶，在阳光之下，真是灿烂辉煌。大殿正中的镂空精雕镏金龙椅，不用说也知道就是九龙宝座。宝座周围是六根沥粉金漆的蟠龙柱，御座前有造型美观的仙鹤和炉鼎。座后是精雕细刻的围屏。每日圣上在此上朝问政，治理天下。据说这龙椅居于大地正中。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_78]],["left"]=[[fb37_77]],["name"]=[[太和殿]],["permission"]=1,["right"]=[[fb37_79]],["role1"]=[[fb37r78_1]],["role2"]=[[fb37r78_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_75]]},["fb37_79"]={["dsc"]=[[这里是三大殿周围的通道。宫禁森严，天威莫测，来来往往的宫女太监虽然很多，可是谁也不敢带出一点声来。]],["id"]=[[fb37_79]],["left"]=[[fb37_78]],["name"]=[[永巷]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb37_72]]},["fb37_80"]={["down"]=[[fb37_83]],["dsc"]=[[这座气宇恢弘的建筑便是督御府。门上是御赐额的督御府牌匾，建筑处处都有鎏金的设计，显得十分豪华而奢侈。此处虽然没有重兵把守，但处处隐藏着视线，气氛十分压抑。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_80]],["item1"]=[[fb37item77]],["name"]=[[督御府]],["permission"]=2,["role1"]=[[fb37r80_1]],["role2"]=[[fb37r80_4]],["stepMusic"]=[[jiaobu]]},["fb37_81"]={["down"]=[[fb37_84]],["dsc"]=[[这个巨大的台基建在皇城的中轴线上，有三层台阶，中间是铺了地毯的御道。东西两侧各是一个日晷和一个嘉量。四周都是汉白玉雕刻栏板，景象无比壮观。三层台基每层都呈须弥座形，四周汉白玉栏杆环绕，栏杆上共有一千四百五十八根望柱。]],["id"]=[[fb37_81]],["name"]=[[台基]],["permission"]=1,["role1"]=[[fb37r81_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_78]]},["fb37_82"]={["down"]=[[fb37_94]],["dsc"]=[[西华门是皇帝和后妃们去京西苑囿及回宫时出入皇宫之门。门外设有下马碑石，碑刻:官员人等至此下马。文武百官到达此地，文官必须下轿，武官必须下马，不得违背。]],["id"]=[[fb37_82]],["item1"]=[[fb37item20]],["name"]=[[西华门]],["permission"]=1,["right"]=[[fb37_83]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_63]]},["fb37_83"]={["down"]=[[fb37_88]],["dsc"]=[[这是武英殿，在这陈列的是各式各样的物饰仪器。原来这里是皇帝斋戒之处。后来这里又是都御府属下的造办处，并在此设立修书处，拣派翰林儒臣校刊书籍。此处的新书遂称“殿版”书。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_83]],["item1"]=[[fb37item79]],["item2"]=[[fb37item88]],["left"]=[[fb37_82]],["name"]=[[武英殿]],["permission"]=1,["right"]=[[fb37_84]],["role1"]=[[fb37r83_1]],["role2"]=[[fb37r83_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_80]]},["fb37_84"]={["down"]=[[fb37_89]],["dsc"]=[[这个大广场的地面铺的石砖横七竖八，共一十五层。是皇帝为防有人挖地道入宫特地设计的。可想皇城的戒备森严之至。]],["id"]=[[fb37_84]],["item1"]=[[fb37item51]],["left"]=[[fb37_83]],["name"]=[[大广场]],["permission"]=1,["right"]=[[fb37_85]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_81]]},["fb37_85"]={["down"]=[[fb37_91]],["dsc"]=[[这里是文华殿，在这陈列着许许多多千奇百怪的奇珍异宝。这里是皇帝举行经筵讲习的地方，每年春秋两季，由经筵讲官在此向皇帝讲解四书五经，再由皇帝复讲一遍，并有王公大臣陪读。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_85]],["item1"]=[[fb37item81]],["left"]=[[fb37_84]],["leftDown"]=[[fb37_90]],["name"]=[[文华殿]],["permission"]=2,["right"]=[[fb37_86]],["rightDown"]=[[fb37_92]],["role1"]=[[fb37item59]],["role2"]=[[fb37item60]],["stepMusic"]=[[jiaobu]]},["fb37_86"]={["down"]=[[fb37_98]],["dsc"]=[[东华门是朝臣和内官员们平时进出皇宫之门。门外设有下马碑石，碑刻:官员人等至此下马。文武百官到达此地，文官必须下轿，武官必须下马，不得违背。]],["id"]=[[fb37_86]],["left"]=[[fb37_85]],["name"]=[[东华门]],["permission"]=2,["role1"]=[[fb37r86_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_68]]},["fb37_87"]={["dsc"]=[[角楼中央是一个三开间的方亭楼，四出抱厦。最顶部十字脊镀金宝顶以下，计有三层檐，九梁，十八柱，七十二条脊，上下重叠，纵横交错。底座是白玉石台基周围饰以白玉栏杆。它紧扼内城一角，能控制四下，内城四角各有一座这样的角楼，若有风吹草动，都可一清二楚。]],["id"]=[[fb37_87]],["leftDown"]=[[fb37_94]],["name"]=[[角楼]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb37_88"]={["dsc"]=[[南熏殿里的木构，藻井和天花，彩画均极富丽。凡立新帝，都要在这里给其母后上尊号，并举行册封大典，阁臣在此写金宝册。这里存着历代帝后及先圣名贤的图像。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_88]],["name"]=[[南熏殿]],["permission"]=1,["role1"]=[[fb37r88_1]],["role2"]=[[fb37r88_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_83]]},["fb37_89"]={["down"]=[[fb37_96]],["dsc"]=[[这是三大殿的前门。门前立着一对铜铸狮子，东边是只雄狮前足踏绣球，象征权力和统一寰宇。西边是只雌狮，前肢抚弄一小乳狮，象征子嗣昌盛。]],["id"]=[[fb37_89]],["name"]=[[太和门]],["permission"]=1,["role1"]=[[fb37item56]],["role2"]=[[fb37item57]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_84]]},["fb37_90"]={["dsc"]=[[内阁大堂内设典籍库，主要收集国朝、档案，实录和圣训等书。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_90]],["name"]=[[内阁大堂]],["permission"]=2,["rightUp"]=[[fb37_85]],["role1"]=[[fb37r90_1]],["role2"]=[[fb37r90_2]],["stepMusic"]=[[jiaobu]]},["fb37_91"]={["dsc"]=[[这里是中央图书馆。收藏了《国史》，《历朝志》，《古今图书集成》，《武英殿聚珍版丛书》等豪著。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_91]],["item1"]=[[fb37item65]],["name"]=[[文渊阁]],["permission"]=2,["role1"]=[[fb37item61]],["role2"]=[[fb37item62]],["role3"]=[[fb37item63]],["role4"]=[[fb37item64]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_85]]},["fb37_92"]={["dsc"]=[[国史馆是翰林儒臣们奉敕纂修国史等书的常设机构。这里的藏书颇多。主要是方志和史书。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb37_92]],["leftUp"]=[[fb37_85]],["name"]=[[国史馆]],["permission"]=2,["role1"]=[[fb37r92_1]],["role2"]=[[fb37r92_2]],["stepMusic"]=[[jiaobu]]},["fb37_93"]={["dsc"]=[[角楼中央是一个三开间的方亭楼，四出抱厦。最顶部十字脊镀金宝顶以下，计有三层檐，九梁，十八柱，七十二条脊，上下重叠，纵横交错。底座是白玉石台基周围饰以白玉栏杆。它紧扼内城一角，能控制四下，内城四角各有一座这样的角楼，若有风吹草动，都可一清二楚。]],["id"]=[[fb37_93]],["name"]=[[角楼]],["permission"]=2,["rightDown"]=[[fb37_98]],["role1"]=[[fb37r93_1]],["stepMusic"]=[[jiaobu]]},["fb37_94"]={["dsc"]=[[这里是内城的一角，头上的天空只能见方方的一角。上面有座漂亮的角楼。]],["id"]=[[fb37_94]],["name"]=[[城角]],["permission"]=2,["right"]=[[fb37_95]],["rightUp"]=[[fb37_87]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_82]]},["fb37_95"]={["dsc"]=[[这是内外城间的宫道。平日里一些人物出入内宫，就是走这路的。这宫道上每日都有御林军来回巡逻，出入可要小心。宫道两边高高的红墙，正是为了拦阻入侵高手的。]],["id"]=[[fb37_95]],["item1"]=[[fb37item23]],["item2"]=[[bfitem5]],["left"]=[[fb37_94]],["name"]=[[宫道]],["permission"]=1,["right"]=[[fb37_96]],["stepMusic"]=[[jiaobu]]},["fb37_96"]={["down"]=[[fb37_103]],["dsc"]=[[午门是城的正门，是皇帝送军出征和受降的地方。五丈高的暗红色城墙上，建有五座崇楼，因此俗称“五凤楼”。台上正中是个大门楼，进深五间，面阔九间，呈“九五”格局。下有五个门洞，重檐庑殿顶。城门主楼凹进，两翼张出，东西四座重檐四角攒顶式方形阙亭，以十三廊庑联接，辅翼着正楼，形如雁翅，气势巍峨。]],["id"]=[[fb37_96]],["item1"]=[[fb37item90]],["left"]=[[fb37_95]],["name"]=[[午门]],["permission"]=1,["right"]=[[fb37_97]],["role1"]=[[fb37r96_1]],["role2"]=[[fb37r96_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb37_89]]},["fb37_97"]={["dsc"]=[[这是内外城间的宫道。平日里一些人物出入内宫，就是走这路的。这宫道上每日都有御林军来回巡逻，出入可要小心。宫道两边高高的红墙，正是为了拦阻入侵高手的。]],["id"]=[[fb37_97]],["item1"]=[[fb37item25]],["left"]=[[fb37_96]],["name"]=[[宫道]],["permission"]=1,["right"]=[[fb37_98]],["stepMusic"]=[[jiaobu]]},["fb37_98"]={["